interface Command { execute(): void; undo?(): void }

class InsertText implements Command {
  constructor(private readonly doc: Document, private readonly text: string) {}
  execute(): void { this.doc.insert(this.text) }
  undo(): void { this.doc.deleteLast(this.text.length) }
}

// data-oriented alternative, dispatched on the discriminant:
type Edit = { kind: "insert"; pos: number; text: string }
          | { kind: "delete"; pos: number; len: number };
